const mode = 'dark';   // inferred type: 'dark' (literal)
let theme = 'dark';    // inferred type: string (widened)

theme = 'light';       // allowed — let is reassignable
// mode = 'light';     // would be a compile error — const, type 'dark'

console.log(mode, theme);
console.log(typeof mode, typeof theme);

