solution.code:
function discount(price: number, rate: number) {
  const off = price * rate; // inferred: number
  return price - off;       // return type inferred: number
}

console.log(discount(100, 0.2));

brokenCode.code:
const totals = []; // no value to infer from -> inferred any[]

totals.push(10);
totals.push('oops'); // no error: any[] accepts anything

console.log(totals);

solution.code:
const totals: number[] = []; // annotate when there's nothing to infer

totals.push(10);
// totals.push('oops'); // now a compile error — caught!

console.log(totals);

function sum(nums: number[]) {
  let total = 0; // inferred: number
  for (const n of nums) {
    total = total + n;
  }
  return total; // return type inferred: number
}

console.log(sum([1, 2, 3, 4]));

alternativeApproaches.code:
function sum(nums: number[]): number {
  let total = 0;
  for (const n of nums) total += n;
  return total;
}
